from datetime import date, timedelta
from typing import Dict, Optional, Set


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books: Set[str] = set()
        # book_id -> (user, borrow_date)
        self.borrowed_books: Dict[str, tuple[str, date]] = {}
        # user -> set of book_ids currently borrowed
        self.user_books: Dict[str, Set[str]] = {}
        # user -> total unpaid fines
        self.fines: Dict[str, float] = {}

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book '{book_id}' does not exist in library.")
        if book_id in self.borrowed_books:
            raise ValueError(f"Book '{book_id}' is already borrowed.")

        user_current_books = self.user_books.get(user, set())
        has_unpaid_fines = self.unpaid_fines(user) > 0.0

        # Requirement 1: A user with unpaid fines may hold at most one book at a time.
        if has_unpaid_fines and len(user_current_books) >= 1:
            raise ValueError(
                f"User '{user}' has unpaid fines and cannot borrow more than 1 book."
            )

        self.borrowed_books[book_id] = (user, day)
        self.user_books.setdefault(user, set()).add(book_id)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        """Return a book; returns the fine charged for this return."""
        # Requirement 4: Returning a book that the user has not borrowed raises ValueError.
        if (
            book_id not in self.borrowed_books
            or self.borrowed_books[book_id][0] != user
        ):
            raise ValueError(f"User '{user}' has not borrowed book '{book_id}'.")

        _, borrow_date = self.borrowed_books.pop(book_id)
        self.user_books[user].remove(book_id)

        due_date = borrow_date + timedelta(days=self.loan_days)

        fine = 0.0
        if day > due_date:
            # Count overdue business days (excluding Saturdays and Sundays)
            late_days = 0
            cur = due_date + timedelta(days=1)
            while cur <= day:
                # weekday(): Monday is 0, Sunday is 6. Weekdays are 0 to 4.
                if cur.weekday() < 5:
                    late_days += 1
                cur += timedelta(days=1)

            fine = late_days * self.daily_fine

        if fine > 0.0:
            self.fines[user] = self.fines.get(user, 0.0) + fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        """Pay all fines of the user."""
        self.fines[user] = 0.0
```

